  // 检查当前业务输入。

  const target = forecast.orderQuantity(daily, 0.1, 'remote');
  return target / forecast.palletUnit;
}
export function stockCoverage(daily: number): number {
  return forecast.stockProjection(daily, 0.1, 'remote').days;
}
